/* Shared tariff configuration rules; browser copies are generated by scripts/sync-source-status.js. */
(function (root, factory) {
  if (typeof module === 'object' && module.exports) module.exports = factory();
  else root.TariffConfig = factory();
})(typeof globalThis !== 'undefined' ? globalThis : this, function () {
  'use strict';
  function minutes(value) {
    if (typeof value !== 'string' || !/^([01]\d|2[0-3]):00$/.test(value))
      throw new Error('Ange hela timmar i formatet HH:00 (00:00–23:00).');
    return Number(value.slice(0, 2)) * 60;
  }
  function selection(values, min, max, message) {
    if (
      !Array.isArray(values) ||
      !values.length ||
      new Set(values).size !== values.length ||
      values.some((value) => !Number.isInteger(value) || value < min || value > max)
    )
      throw new Error(message);
  }
  function validateTariff(tariff) {
    if (!tariff || typeof tariff !== 'object' || Array.isArray(tariff))
      throw new Error('Tariffparametrar saknas.');
    const from = minutes(tariff.start),
      to = minutes(tariff.end);
    if (from >= to) throw new Error('Sluttiden måste vara senare än starttiden inom samma dygn.');
    selection(tariff.weekdays, 0, 6, 'Ange unika veckodagar 0–6 (0 = söndag).');
    if (!Number.isFinite(tariff.rateSekPerKw) || tariff.rateSekPerKw < 0)
      throw new Error('Ange ett effektpris på minst 0 kr/kW.');
    if (!Number.isInteger(tariff.peakCount) || tariff.peakCount < 1 || tariff.peakCount > 31)
      throw new Error('Antal timtoppar måste vara ett heltal mellan 1 och 31.');
    if (typeof tariff.distinctDays !== 'boolean')
      throw new Error('Välj om topparna ska komma från olika dagar.');
    if (tariff.months !== undefined)
      selection(tariff.months, 1, 12, 'Välj unika månader 1–12 eller Hela året.');
    if (tariff.calendar !== undefined && !['none', 'se-telge'].includes(tariff.calendar))
      throw new Error('Välj en giltig helgdagskalender.');
    return { from, to };
  }
  function parseTariffForm(raw) {
    if (typeof raw.weekdays !== 'string' || !/^\s*[0-6]\s*(,\s*[0-6]\s*)*$/.test(raw.weekdays))
      throw new Error(
        'Ange veckodagar 0–6 separerade med komma, utan tomma eller upprepade värden.',
      );
    for (const [key, label] of [
      ['peakCount', 'antal timtoppar'],
      ['rateSekPerKw', 'effektpris'],
    ])
      if (typeof raw[key] !== 'string' || !raw[key].trim()) throw new Error(`Fyll i ${label}.`);
    if (typeof raw.allYear !== 'boolean') throw new Error('Välj månader eller Hela året.');
    const tariff = {
      start: raw.start,
      end: raw.end,
      weekdays: raw.weekdays.split(',').map((value) => Number(value.trim())),
      peakCount: Number(raw.peakCount),
      rateSekPerKw: Number(raw.rateSekPerKw),
      distinctDays:
        raw.distinctDays === 'true' ? true : raw.distinctDays === 'false' ? false : null,
    };
    if (raw.calendar && raw.calendar !== 'none') tariff.calendar = raw.calendar;
    if (!raw.allYear) tariff.months = raw.months;
    validateTariff(tariff);
    return tariff;
  }
  function tariffKey(tariff) {
    validateTariff(tariff);
    return JSON.stringify([
      tariff.start,
      tariff.end,
      [...tariff.weekdays].sort((a, b) => a - b),
      tariff.peakCount,
      tariff.rateSekPerKw,
      tariff.distinctDays,
      tariff.calendar || 'none',
      [...(tariff.months || Array.from({ length: 12 }, (_, i) => i + 1))].sort((a, b) => a - b),
    ]);
  }
  function peakLabel(tariff) {
    try {
      validateTariff(tariff);
    } catch {
      return 'Medel av timtoppar';
    }
    return `Medel av ${tariff.peakCount} ${tariff.peakCount === 1 ? 'timtopp' : 'timtoppar'}`;
  }
  function currentMonth(now = new Date()) {
    return new Intl.DateTimeFormat('sv-SE', {
      timeZone: 'Europe/Stockholm',
      year: 'numeric',
      month: '2-digit',
    }).format(now);
  }
  function matchesResult(result, tariff, now = new Date()) {
    try {
      return result?.month === currentMonth(now) && result.tariffKey === tariffKey(tariff);
    } catch {
      return false;
    }
  }
  return { validateTariff, parseTariffForm, tariffKey, peakLabel, currentMonth, matchesResult };
});
